questionvariables.text:
/* Design: best whole-number combination, not the corner of the region. Source: adapted from SMP Book 5 (Metric), Chapter 8, Section 2.3. Vertex fractions with denominators 2, 4, 5; rounding to the nearest is outside R; rounding down is inside R but not best. Profits in Ksh (list scale x the context's Ksh step). */
Q32L: [["A carpenter in Kericho makes \\(x\\) chairs and \\(y\\) tables a week. Each of the chairs needs \\(4\\) metres of timber and each of the tables needs \\(7\\); there are \\(44\\) metres of timber. Each of the chairs needs \\(9\\) hours of workshop time and each of the tables needs \\(2\\); there are \\(33\\) hours of workshop time. The profit is Ksh \\(400\\) on each of the chairs and Ksh \\(500\\) on each of the tables.",[4,7,"<=",44],[9,2,"<=",33],400,500,[13/5,24/5],[2,5],3300,3440,[3,5],[2,4],"(2.6, 4.8)","4 \\times 3 + 7 \\times 5 = 47 \\gt 44",["metres of timber","hours of workshop time"]],
["A knitting group in Nyahururu makes \\(x\\) pairs of school socks and \\(y\\) school sweaters a week. Each of the pairs of school socks needs \\(1\\) units of wool and each of the school sweaters needs \\(7\\); there are \\(33\\) units of wool. Each of the pairs of school socks needs \\(7\\) hours of knitting time and each of the school sweaters needs \\(4\\); there are \\(69\\) hours of knitting time. The profit is Ksh \\(50\\) on each of the pairs of school socks and Ksh \\(30\\) on each of the school sweaters.",[1,7,"<=",33],[7,4,"<=",69],50,30,[39/5,18/5],[8,3],490,498,[8,4],[7,3],"(7.8, 3.6)","1 \\times 8 + 7 \\times 4 = 36 \\gt 33",["units of wool","hours of knitting time"]],
["A farmer in Ol Kalou makes \\(x\\) sacks of cabbages and \\(y\\) sacks of carrots a week. Each of the sacks of cabbages needs \\(3\\) units of space on the lorry and each of the sacks of carrots needs \\(7\\); there are \\(46\\) units of space on the lorry. Each of the sacks of cabbages needs \\(9\\) minutes of loading time and each of the sacks of carrots needs \\(1\\); there are \\(22\\) minutes of loading time. The profit is Ksh \\(400\\) on each of the sacks of cabbages and Ksh \\(900\\) on each of the sacks of carrots.",[3,7,"<=",46],[9,1,"<=",22],400,900,[9/5,29/5],[1,6],5800,5940,[2,6],[1,5],"(1.8, 5.8)","3 \\times 2 + 7 \\times 6 = 48 \\gt 46",["units of space on the lorry","minutes of loading time"]],
["A tailor in Machakos makes \\(x\\) school bags and \\(y\\) sports kits a week. Each of the school bags needs \\(1\\) metres of cloth and each of the sports kits needs \\(1\\); there are \\(13\\) metres of cloth. Each of the school bags needs \\(6\\) hours of sewing time and each of the sports kits needs \\(1\\); there are \\(41\\) hours of sewing time. The profit is Ksh \\(500\\) on each of the school bags and Ksh \\(400\\) on each of the sports kits.",[1,1,"<=",13],[6,1,"<=",41],500,400,[28/5,37/5],[5,8],5700,5760,[6,7],[5,7],"(5.6, 7.4)","6 \\times 6 + 1 \\times 7 = 43 \\gt 41",["metres of cloth","hours of sewing time"]],
["A carpenter in Kabarnet makes \\(x\\) beehives and \\(y\\) bird boxes a week. Each of the beehives needs \\(1\\) planks of timber and each of the bird boxes needs \\(1\\); there are \\(14\\) planks of timber. Each of the beehives needs \\(7\\) hours of carpentry time and each of the bird boxes needs \\(2\\); there are \\(66\\) hours of carpentry time. The profit is Ksh \\(900\\) on each of the beehives and Ksh \\(700\\) on each of the bird boxes.",[1,1,"<=",14],[7,2,"<=",66],900,700,[38/5,32/5],[7,7],11200,11320,[8,6],[7,6],"(7.6, 6.4)","7 \\times 8 + 2 \\times 6 = 68 \\gt 66",["planks of timber","hours of carpentry time"]],
["A fruit trader in Murang'a makes \\(x\\) baskets of tomatoes and \\(y\\) crates of avocados a week. Each of the baskets of tomatoes needs \\(4\\) units of space in the pickup and each of the crates of avocados needs \\(7\\); there are \\(55\\) units of space in the pickup. Each of the baskets of tomatoes needs \\(7\\) hours of packing time and each of the crates of avocados needs \\(1\\); there are \\(31\\) hours of packing time. The profit is Ksh \\(700\\) on each of the baskets of tomatoes and Ksh \\(900\\) on each of the crates of avocados.",[4,7,"<=",55],[7,1,"<=",31],700,900,[18/5,29/5],[3,6],7500,7740,[4,6],[3,5],"(3.6, 5.8)","4 \\times 4 + 7 \\times 6 = 58 \\gt 55",["units of space in the pickup","hours of packing time"]],
["A dairy in Eldama Ravine makes \\(x\\) packets of yoghurt and \\(y\\) packets of mala a week. Each of the packets of yoghurt needs \\(1\\) litres of milk and each of the packets of mala needs \\(9\\); there are \\(18\\) litres of milk. Each of the packets of yoghurt needs \\(7\\) units of fridge space and each of the packets of mala needs \\(8\\); there are \\(38\\) units of fridge space. The profit is Ksh \\(500\\) on each of the packets of yoghurt and Ksh \\(600\\) on each of the packets of mala.",[1,9,"<=",18],[7,8,"<=",38],500,600,[18/5,8/5],[4,1],2600,2760,[4,2],[3,1],"(3.6, 1.6)","1 \\times 4 + 9 \\times 2 = 22 \\gt 18",["litres of milk","units of fridge space"]],
["A welder in Kisii makes \\(x\\) door frames and \\(y\\) window frames a week. Each of the door frames needs \\(1\\) metres of steel and each of the window frames needs \\(1\\); there are \\(12\\) metres of steel. Each of the door frames needs \\(6\\) hours of welding time and each of the window frames needs \\(1\\); there are \\(40\\) hours of welding time. The profit is Ksh \\(900\\) on each of the door frames and Ksh \\(500\\) on each of the window frames.",[1,1,"<=",12],[6,1,"<=",40],900,500,[28/5,32/5],[5,7],8000,8240,[6,6],[5,6],"(5.6, 6.4)","6 \\times 6 + 1 \\times 6 = 42 \\gt 40",["metres of steel","hours of welding time"]],
["A tree nursery in Embu makes \\(x\\) trays of seedlings and \\(y\\) potted plants a week. Each of the trays of seedlings needs \\(1\\) kg of potting soil and each of the potted plants needs \\(9\\); there are \\(57\\) kg of potting soil. Each of the trays of seedlings needs \\(7\\) minutes of watering time and each of the potted plants needs \\(3\\); there are \\(51\\) minutes of watering time. The profit is Ksh \\(70\\) on each of the trays of seedlings and Ksh \\(90\\) on each of the potted plants.",[1,9,"<=",57],[7,3,"<=",51],70,90,[24/5,29/5],[5,5],800,858,[5,6],[4,5],"(4.8, 5.8)","1 \\times 5 + 9 \\times 6 = 59 \\gt 57",["kg of potting soil","minutes of watering time"]],
["A women's group in Makueni makes \\(x\\) kiondo baskets and \\(y\\) table mats a week. Each of the kiondo baskets needs \\(7\\) kg of sisal and each of the table mats needs \\(5\\); there are \\(30\\) kg of sisal. Each of the kiondo baskets needs \\(7\\) hours of weaving time and each of the table mats needs \\(1\\); there are \\(20\\) hours of weaving time. The profit is Ksh \\(700\\) on each of the kiondo baskets and Ksh \\(400\\) on each of the table mats.",[7,5,"<=",30],[7,1,"<=",20],700,400,[5/2,5/2],[2,3],2600,2750,[3,3],[2,2],"(2.5, 2.5)","7 \\times 3 + 5 \\times 3 = 36 \\gt 30",["kg of sisal","hours of weaving time"]]];
ix: 1+rand(10);
E: Q32L[ix];
a1: E[2][1]; b1: E[2][2]; c1: E[2][4]; a2: E[3][1]; b2: E[3][2]; c2: E[3][4];
pp: E[4]; pq: E[5]; vv: E[6]; bst: E[7]; t: E[8]; tv: E[9]; rp: E[10]; fl: E[11]; vd: E[12]; brkd: E[13]; un: E[14];
Pof(u, w) := pp*u + pq*w;
prnd: Pof(rp[1], rp[2]);
validate_int(ex) := if integerp(ev(ex, simp)) then "" else "Type whole numbers.";
g3(v) := block([q,r], if v < 1000 then string(v) else (q: floor(v/1000), r: v - 1000*q, sconcat(g3(q), "\\,", if r < 10 then "00" elseif r < 100 then "0" else "", string(r))));
thou(v) := if abs(v) < 10000 then string(v) else g3(v);
